<?php $esEstudiante=ControladorPermisos::esEstudiante();$e=static function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};$secciones=$esEstudiante?[]:ControladorAsistencias::crtSecciones();$resumen=$esEstudiante?ControladorAsistencias::crtResumenEstudiante(ControladorPermisos::idEstudianteContexto()):[];?>
<section class="content page-fade"><div class="container-fluid"><div class="entity-hero mb-4"><div class="entity-hero__content"><span class="entity-kicker mb-3">Seguimiento académico</span><h1 class="entity-title mb-2">Asistencia</h1><p class="entity-lead mb-0"><?php echo $esEstudiante?'Tu asistencia por curso y materia.':'Elegí una materia para tomar asistencia o consultar su historial.';?></p></div></div>
<?php if($esEstudiante):?><div class="row"><?php foreach($resumen as $r):?><div class="col-md-6 col-xl-4 mb-3"><div class="card glass-card h-100"><div class="card-body"><small class="text-muted text-uppercase"><?php echo $e($r['curso']);?></small><h4><?php echo $e($r['materia']);?></h4><div class="display-4 font-weight-bold text-primary"><?php echo $e($r['porcentaje']);?>%</div><p class="text-muted">Asistencia computada</p><div class="d-flex flex-wrap" style="gap:.4rem"><span class="badge badge-success">Presentes <?php echo (int)$r['presentes'];?></span><span class="badge badge-danger">Ausentes <?php echo (int)$r['ausentes'];?></span><span class="badge badge-warning">Tardanzas <?php echo (int)$r['tardanzas'];?></span><span class="badge badge-info">Justificadas <?php echo (int)$r['justificadas'];?></span></div></div></div></div><?php endforeach;?></div><?php if(!$resumen):?><div class="empty-state"><i class="fas fa-calendar-check"></i><h4>Todavía no hay asistencias registradas</h4></div><?php endif;?>
<?php else:?><div class="row"><?php foreach($secciones as $s):?><div class="col-md-6 col-xl-4 mb-3"><div class="card glass-card h-100"><div class="card-body"><small class="text-muted text-uppercase"><?php echo $e($s['curso']);?></small><h4><?php echo $e($s['materia']);?></h4><p class="text-muted"><?php echo $e($s['docente']);?></p><p><strong><?php echo (int)$s['clases'];?></strong> clases registradas</p><a class="btn btn-primary btn-sm" href="index.php?r=asistencia-seccion&amp;idSeccion=<?php echo (int)$s['idSeccion'];?>"><i class="fas fa-user-check mr-1"></i>Abrir asistencia</a></div></div></div><?php endforeach;?></div><?php endif;?></div></section>
